import {replacePageMarkup} from './stable-surface.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountSettingsBackupView(container,{session}={}){
 const lifetime=new AbortController();let disposed=false,includeChat=false,includeCredentials=false;
 function render(){
  if(disposed)return;const state=session.inspect(),busy=['exporting','reading','restoring'].includes(state.status),file=state.file;
  replacePageMarkup(container,`<div class="ui-field"><label class="ui-choice ui-choice--control-only ui-hit-owner"><input type="checkbox" data-backup-option="chat" ${includeChat?'checked':''} ${busy?'disabled':''}><span>导出时包含当前聊天设置</span></label><label class="ui-choice ui-choice--control-only ui-hit-owner"><input type="checkbox" data-backup-option="credentials" ${includeCredentials?'checked':''} ${busy?'disabled':''}><span>导出时包含 API 密钥</span></label>${includeCredentials?'<p class="lt-meta">备份文件将包含 API 密钥，请自行保管。</p>':''}<div class="lt-settings-row"><button type="button" class="ui-button ui-button--secondary" data-backup-action="export" ${busy?'disabled':''}>导出设置</button><button type="button" class="ui-button ui-button--secondary" data-backup-action="import" ${busy?'disabled':''}>导入设置</button></div><input type="file" accept=".json,application/json" data-backup-file hidden>${file?`<div class="ui-field"><strong class="ui-field__label">${esc(file.name)}</strong><p class="lt-meta">${esc(file.exportedAt.slice(0,10))} · v${esc(file.pluginVersion)}${file.includesCredentials?' · 含 API 密钥':''}</p><p>${file.sections.map(esc).join('、')}</p><div class="lt-settings-row"><button type="button" class="ui-button ui-button--secondary" data-backup-action="cancel" ${busy?'disabled':''}>取消</button><button type="button" class="ui-button ui-button--primary" data-backup-action="restore" ${busy?'disabled':''}>恢复设置</button></div></div>`:''}${state.missingCredentials.length?`<p class="lt-meta">需填写密钥：${state.missingCredentials.map(esc).join('、')}</p>`:''}<p class="${state.status==='error'?'lt-error':'lt-status'}" data-backup-status role="status" ${state.message?'':'hidden'}>${esc(state.message)}</p></div>`);
 }
 container.addEventListener('change',event=>{if(event.target.matches?.('[data-backup-option]')){if(event.target.dataset.backupOption==='chat')includeChat=event.target.checked;else includeCredentials=event.target.checked;render();}else if(event.target.matches?.('[data-backup-file]')){const file=event.target.files?.[0];if(file)void session.readFile(file);}}, {signal:lifetime.signal});
 container.addEventListener('click',event=>{const action=event.target.closest?.('[data-backup-action]');if(!action||action.disabled)return;switch(action.dataset.backupAction){case'export':void session.exportFile({includeChat,includeCredentials});break;case'import':container.querySelector('[data-backup-file]')?.click();break;case'cancel':session.cancel();break;case'restore':void session.restore();break;}}, {signal:lifetime.signal});
 const off=session.subscribe(render);render();return {dispose(){disposed=true;lifetime.abort();off();session.cancel();}};
}
